import{_ as t,o,c as a,a4 as d}from"./chunks/framework.DA9C4Pbl.js";const p=JSON.parse('{"title":"Environment (.env)","description":"","frontmatter":{"title":"Environment (.env)","visibility":"public","audience":"operator","tier":"reference","source":"generated","cli":"4.5.0","template":"7.7"},"headers":[],"relativePath":"reference/compose/environment.md","filePath":"reference/compose/environment.md"}'),r={name:"reference/compose/environment.md"};function s(n,e,c,i,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="environment-env" tabindex="-1">Environment (.env) <a class="header-anchor" href="#environment-env" aria-label="Permalink to “Environment (.env)”">​</a></h1><p>Every key the <code>.env</code> file next to <code>docker-compose.yml</code> can hold: the ones <code>arcsecond setup</code> writes, the ones you fill in, and the ones only the backend reads. Compose reads this file and hands the values to the containers; a container keeps the values it was created with, so after editing it run <code>arcsecond restart</code>.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>A <code>$</code> in a value is interpolated by compose. Quotes, backslashes and <code>#</code> break the parse. Keep values plain.</p></div><table tabindex="0"><thead><tr><th>Key</th><th>Who sets it</th><th>What it is for</th></tr></thead><tbody><tr><td><code>SECRET_KEY</code></td><td>written by <code>arcsecond setup</code></td><td>Django&#39;s secret key: signs sessions and tokens. Generated once; changing it logs everyone out.</td></tr><tr><td><code>AUTH_JWT_SIGNING_KEY</code></td><td>written by <code>arcsecond setup</code></td><td>Signs the access tokens of the web interface and the CLI. Changing it logs everyone out.</td></tr><tr><td><code>AGENT_JWT_SIGNING_KEY</code></td><td>written by <code>arcsecond setup</code></td><td>Signs the tokens of the equipment agents talking to the Control Room.</td></tr><tr><td><code>FIELD_ENCRYPTION_KEY</code></td><td>written by <code>arcsecond setup</code></td><td>Encrypts sensitive fields in the database — external-storage credentials among them. Losing it makes those fields unreadable.</td></tr><tr><td><code>SHARED_DATA_PATH</code></td><td>written by <code>arcsecond setup</code></td><td>The folder on this machine where the installation keeps everything it persists: data files, previews, caches, database backups. Mounted as /data inside the containers. Asked at setup.</td></tr><tr><td><code>POSTGRES_USER</code></td><td>written by <code>arcsecond setup</code></td><td>The database role. Stable across installs.</td></tr><tr><td><code>POSTGRES_PASSWORD</code></td><td>written by <code>arcsecond setup</code></td><td>The role&#39;s password, generated per install. Only read by Postgres on the very first boot; rotate it with <code>arcsecond db set-password</code>, never by editing this line alone.</td></tr><tr><td><code>POSTGRES_DB</code></td><td>written by <code>arcsecond setup</code></td><td>The database name.</td></tr><tr><td><code>GCN_CONSUMER_CLIENT_ID</code></td><td>set by the operator</td><td>NASA GCN client credentials for the optional transient-alerts service. Empty until you paste yours.</td></tr><tr><td><code>GCN_CONSUMER_CLIENT_SECRET</code></td><td>set by the operator</td><td>See GCN_CONSUMER_CLIENT_ID.</td></tr><tr><td><code>TOMORROW_IO_API_KEY</code></td><td>set by the operator</td><td>Your own Tomorrow.io API key: the weather forecast, and the safety conditions only a forecast can feed (cloud cover, humidity) where no station of yours measures them. A free key from <a href="https://www.tomorrow.io/weather-api/" target="_blank" rel="noreferrer">https://www.tomorrow.io/weather-api/</a> is enough; the backend asks once an hour per observing site. Arcsecond&#39;s key is not shipped. Empty: no forecast, and the Safety strip says so. Asked at setup, or <code>arcsecond setup --tomorrow-io-key KEY</code>.</td></tr><tr><td><code>FINK_ENABLED</code></td><td>read by the backend</td><td><code>false</code> turns off the survey alerts from Fink in the optional transient-alerts service; GCN keeps running. Fink needs no credentials, so it is on wherever the service runs.</td></tr><tr><td><code>FINK_KAFKA_GROUP_ID</code></td><td>read by the backend</td><td>The installation&#39;s consumer group at Fink. Empty: <code>arcsecond-local-</code> and this machine&#39;s fingerprint, which no other installation shares. Two installations sharing a group split the alerts between them.</td></tr><tr><td><code>FINK_TOPICS</code></td><td>read by the backend</td><td>Comma-separated Fink topics, each ending in its survey (<code>_ztf</code>). Empty: the topics Arcsecond chose.</td></tr><tr><td><code>HOSTED_FRONTEND_HOST</code></td><td>set by the operator</td><td>The address other computers reach the installation at, port included (e.g. 192.168.1.42:5555). The backend builds invitation and password-reset links from it. Empty means localhost:5555. <code>arcsecond setup</code> fills it in with this machine&#39;s network address when it is empty; set it with <code>arcsecond setup --lan-host</code>.</td></tr><tr><td><code>ARCSECOND_OPTIONAL_SERVICES</code></td><td>written by <code>arcsecond setup</code></td><td>The operator&#39;s yes/no answers about optional services (e.g. <code>alerts:yes</code>), so setup does not ask again.</td></tr><tr><td><code>HOSTED_FRONTEND_SCHEME</code></td><td>read by the backend</td><td><code>http</code> (default) or <code>https</code>, when a TLS-terminating reverse proxy of your own sits in front of the installation.</td></tr><tr><td><code>HOSTED_EXTRA_TRUSTED_ORIGINS</code></td><td>read by the backend</td><td>Comma-separated origins, scheme included, to trust besides private-network addresses — a public domain, a Tailscale name. Not needed for a LAN address.</td></tr><tr><td><code>SKY_BRIGHTNESS_GEOTIFF_PATH</code></td><td>written by <code>arcsecond setup</code></td><td>Where the backend finds the sky-brightness map kept on this machine (a path under <code>/data</code>). Empty: the map is looked up on statics.arcsecond.io instead. Change the answer with <code>arcsecond setup --with-sky-map</code> or <code>--without-sky-map</code>.</td></tr><tr><td><code>LIVE_IMAGE_PROXY_URL</code></td><td>read by the backend</td><td>Where the backend reaches the live-image proxy for cameras. Default <a href="http://host.docker.internal:8765" target="_blank" rel="noreferrer">http://host.docker.internal:8765</a>; change it only for a proxy on another machine, then <code>arcsecond restart backend</code>.</td></tr><tr><td><code>LOCAL_EMAIL_VERIFICATION_GRACE_HOURS</code></td><td>read by the backend</td><td>How long a new member may use the installation before verifying their email, on an installation with no mail server.</td></tr><tr><td><code>ARCSECOND_DOWNLOADS_PER_CLIENT</code></td><td>set by the operator</td><td>How many downloads one computer may have open at once; past it, the next one is refused with a 429 until one finishes. Default 6. Then <code>arcsecond restart web</code>.</td></tr><tr><td><code>ARCSECOND_DOWNLOADS_TOTAL</code></td><td>set by the operator</td><td>How many downloads the installation serves at once, all computers together. Default 24.</td></tr><tr><td><code>ARCSECOND_DOWNLOAD_RATE</code></td><td>set by the operator</td><td>The speed of each download, in bytes per second, <code>k</code> and <code>m</code> allowed; <code>0</code> for no limit. Default <code>20m</code>. Lower it when the observers work remotely over a link the downloads would otherwise fill.</td></tr><tr><td><code>ARCSECOND_BACKEND_MEMORY</code></td><td>set by the operator</td><td>The most memory the backend container may use, e.g. <code>6g</code> (the default). Past it, Docker restarts the busiest of its processes rather than letting the machine take memory from the database.</td></tr><tr><td><code>ARCSECOND_WORKER_MEMORY</code></td><td>set by the operator</td><td>The same ceiling for the worker, which runs the exposures and procedures. Default <code>6g</code>.</td></tr><tr><td><code>ARCSECOND_DATA_WORKER_MEMORY</code></td><td>set by the operator</td><td>The same ceiling for the data worker: zip archives, previews, storage pushes, backups. Default <code>3g</code>.</td></tr><tr><td><code>ARCSECOND_DATA_WORKER_CONCURRENCY</code></td><td>set by the operator</td><td>How many jobs the data worker runs at once. Default 2; each can hold a few hundred MB.</td></tr><tr><td><code>ARCSECOND_API_IMAGE</code></td><td>set by the operator</td><td>The image the backend, both workers, beat and the alerts consumer run instead of the published one: one built from the backend&#39;s sources, e.g. <code>arcsecond-api:latest</code>. Empty: the published image. Set ARCSECOND_API_PULL_POLICY to <code>never</code> with it, then <code>arcsecond restart</code>.</td></tr><tr><td><code>ARCSECOND_API_PULL_POLICY</code></td><td>set by the operator</td><td><code>never</code> when ARCSECOND_API_IMAGE names an image that exists on this machine only, so <code>arcsecond update</code> and <code>arcsecond start --pull</code> leave it alone rather than fail to download it. Default <code>missing</code>.</td></tr><tr><td><code>ARCSECOND_WEB_IMAGE</code></td><td>set by the operator</td><td>The image the web interface runs instead of the published one: one built from the webapp&#39;s sources, e.g. <code>arcsecond-web:latest</code>. Empty: the published image. Set ARCSECOND_WEB_PULL_POLICY to <code>never</code> with it, then <code>arcsecond restart web</code>.</td></tr><tr><td><code>ARCSECOND_WEB_PULL_POLICY</code></td><td>set by the operator</td><td><code>never</code> when ARCSECOND_WEB_IMAGE names an image that exists on this machine only, as ARCSECOND_API_PULL_POLICY does for the backend&#39;s. Default <code>missing</code>.</td></tr></tbody></table><h2 id="secret_key" tabindex="-1"><code>SECRET_KEY</code> <a class="header-anchor" href="#secret_key" aria-label="Permalink to “SECRET_KEY”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> Django&#39;s secret key: signs sessions and tokens. Generated once; changing it logs everyone out.</p><h2 id="auth_jwt_signing_key" tabindex="-1"><code>AUTH_JWT_SIGNING_KEY</code> <a class="header-anchor" href="#auth_jwt_signing_key" aria-label="Permalink to “AUTH_JWT_SIGNING_KEY”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> Signs the access tokens of the web interface and the CLI. Changing it logs everyone out.</p><h2 id="agent_jwt_signing_key" tabindex="-1"><code>AGENT_JWT_SIGNING_KEY</code> <a class="header-anchor" href="#agent_jwt_signing_key" aria-label="Permalink to “AGENT_JWT_SIGNING_KEY”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> Signs the tokens of the equipment agents talking to the Control Room.</p><h2 id="field_encryption_key" tabindex="-1"><code>FIELD_ENCRYPTION_KEY</code> <a class="header-anchor" href="#field_encryption_key" aria-label="Permalink to “FIELD_ENCRYPTION_KEY”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> Encrypts sensitive fields in the database — external-storage credentials among them. Losing it makes those fields unreadable.</p><h2 id="shared_data_path" tabindex="-1"><code>SHARED_DATA_PATH</code> <a class="header-anchor" href="#shared_data_path" aria-label="Permalink to “SHARED_DATA_PATH”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> The folder on this machine where the installation keeps everything it persists: data files, previews, caches, database backups. Mounted as /data inside the containers. Asked at setup.</p><h2 id="postgres_user" tabindex="-1"><code>POSTGRES_USER</code> <a class="header-anchor" href="#postgres_user" aria-label="Permalink to “POSTGRES_USER”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> The database role. Stable across installs.</p><h2 id="postgres_password" tabindex="-1"><code>POSTGRES_PASSWORD</code> <a class="header-anchor" href="#postgres_password" aria-label="Permalink to “POSTGRES_PASSWORD”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> The role&#39;s password, generated per install. Only read by Postgres on the very first boot; rotate it with <code>arcsecond db set-password</code>, never by editing this line alone.</p><h2 id="postgres_db" tabindex="-1"><code>POSTGRES_DB</code> <a class="header-anchor" href="#postgres_db" aria-label="Permalink to “POSTGRES_DB”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> The database name.</p><h2 id="gcn_consumer_client_id" tabindex="-1"><code>GCN_CONSUMER_CLIENT_ID</code> <a class="header-anchor" href="#gcn_consumer_client_id" aria-label="Permalink to “GCN_CONSUMER_CLIENT_ID”">​</a></h2><p><em>Set by the operator.</em> NASA GCN client credentials for the optional transient-alerts service. Empty until you paste yours.</p><h2 id="gcn_consumer_client_secret" tabindex="-1"><code>GCN_CONSUMER_CLIENT_SECRET</code> <a class="header-anchor" href="#gcn_consumer_client_secret" aria-label="Permalink to “GCN_CONSUMER_CLIENT_SECRET”">​</a></h2><p><em>Set by the operator.</em> See GCN_CONSUMER_CLIENT_ID.</p><h2 id="tomorrow_io_api_key" tabindex="-1"><code>TOMORROW_IO_API_KEY</code> <a class="header-anchor" href="#tomorrow_io_api_key" aria-label="Permalink to “TOMORROW_IO_API_KEY”">​</a></h2><p><em>Set by the operator.</em> Your own Tomorrow.io API key: the weather forecast, and the safety conditions only a forecast can feed (cloud cover, humidity) where no station of yours measures them. A free key from <a href="https://www.tomorrow.io/weather-api/" target="_blank" rel="noreferrer">https://www.tomorrow.io/weather-api/</a> is enough; the backend asks once an hour per observing site. Arcsecond&#39;s key is not shipped. Empty: no forecast, and the Safety strip says so. Asked at setup, or <code>arcsecond setup --tomorrow-io-key KEY</code>.</p><h2 id="fink_enabled" tabindex="-1"><code>FINK_ENABLED</code> <a class="header-anchor" href="#fink_enabled" aria-label="Permalink to “FINK_ENABLED”">​</a></h2><p><em>Read by the backend.</em> <code>false</code> turns off the survey alerts from Fink in the optional transient-alerts service; GCN keeps running. Fink needs no credentials, so it is on wherever the service runs.</p><h2 id="fink_kafka_group_id" tabindex="-1"><code>FINK_KAFKA_GROUP_ID</code> <a class="header-anchor" href="#fink_kafka_group_id" aria-label="Permalink to “FINK_KAFKA_GROUP_ID”">​</a></h2><p><em>Read by the backend.</em> The installation&#39;s consumer group at Fink. Empty: <code>arcsecond-local-</code> and this machine&#39;s fingerprint, which no other installation shares. Two installations sharing a group split the alerts between them.</p><h2 id="fink_topics" tabindex="-1"><code>FINK_TOPICS</code> <a class="header-anchor" href="#fink_topics" aria-label="Permalink to “FINK_TOPICS”">​</a></h2><p><em>Read by the backend.</em> Comma-separated Fink topics, each ending in its survey (<code>_ztf</code>). Empty: the topics Arcsecond chose.</p><h2 id="hosted_frontend_host" tabindex="-1"><code>HOSTED_FRONTEND_HOST</code> <a class="header-anchor" href="#hosted_frontend_host" aria-label="Permalink to “HOSTED_FRONTEND_HOST”">​</a></h2><p><em>Set by the operator.</em> The address other computers reach the installation at, port included (e.g. 192.168.1.42:5555). The backend builds invitation and password-reset links from it. Empty means localhost:5555. <code>arcsecond setup</code> fills it in with this machine&#39;s network address when it is empty; set it with <code>arcsecond setup --lan-host</code>.</p><h2 id="arcsecond_optional_services" tabindex="-1"><code>ARCSECOND_OPTIONAL_SERVICES</code> <a class="header-anchor" href="#arcsecond_optional_services" aria-label="Permalink to “ARCSECOND_OPTIONAL_SERVICES”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> The operator&#39;s yes/no answers about optional services (e.g. <code>alerts:yes</code>), so setup does not ask again.</p><h2 id="hosted_frontend_scheme" tabindex="-1"><code>HOSTED_FRONTEND_SCHEME</code> <a class="header-anchor" href="#hosted_frontend_scheme" aria-label="Permalink to “HOSTED_FRONTEND_SCHEME”">​</a></h2><p><em>Read by the backend.</em> <code>http</code> (default) or <code>https</code>, when a TLS-terminating reverse proxy of your own sits in front of the installation.</p><h2 id="hosted_extra_trusted_origins" tabindex="-1"><code>HOSTED_EXTRA_TRUSTED_ORIGINS</code> <a class="header-anchor" href="#hosted_extra_trusted_origins" aria-label="Permalink to “HOSTED_EXTRA_TRUSTED_ORIGINS”">​</a></h2><p><em>Read by the backend.</em> Comma-separated origins, scheme included, to trust besides private-network addresses — a public domain, a Tailscale name. Not needed for a LAN address.</p><h2 id="sky_brightness_geotiff_path" tabindex="-1"><code>SKY_BRIGHTNESS_GEOTIFF_PATH</code> <a class="header-anchor" href="#sky_brightness_geotiff_path" aria-label="Permalink to “SKY_BRIGHTNESS_GEOTIFF_PATH”">​</a></h2><p><em>Written by <code>arcsecond setup</code>.</em> Where the backend finds the sky-brightness map kept on this machine (a path under <code>/data</code>). Empty: the map is looked up on statics.arcsecond.io instead. Change the answer with <code>arcsecond setup --with-sky-map</code> or <code>--without-sky-map</code>.</p><h2 id="live_image_proxy_url" tabindex="-1"><code>LIVE_IMAGE_PROXY_URL</code> <a class="header-anchor" href="#live_image_proxy_url" aria-label="Permalink to “LIVE_IMAGE_PROXY_URL”">​</a></h2><p><em>Read by the backend.</em> Where the backend reaches the live-image proxy for cameras. Default <a href="http://host.docker.internal:8765" target="_blank" rel="noreferrer">http://host.docker.internal:8765</a>; change it only for a proxy on another machine, then <code>arcsecond restart backend</code>.</p><h2 id="local_email_verification_grace_hours" tabindex="-1"><code>LOCAL_EMAIL_VERIFICATION_GRACE_HOURS</code> <a class="header-anchor" href="#local_email_verification_grace_hours" aria-label="Permalink to “LOCAL_EMAIL_VERIFICATION_GRACE_HOURS”">​</a></h2><p><em>Read by the backend.</em> How long a new member may use the installation before verifying their email, on an installation with no mail server.</p><h2 id="arcsecond_downloads_per_client" tabindex="-1"><code>ARCSECOND_DOWNLOADS_PER_CLIENT</code> <a class="header-anchor" href="#arcsecond_downloads_per_client" aria-label="Permalink to “ARCSECOND_DOWNLOADS_PER_CLIENT”">​</a></h2><p><em>Set by the operator.</em> How many downloads one computer may have open at once; past it, the next one is refused with a 429 until one finishes. Default 6. Then <code>arcsecond restart web</code>.</p><h2 id="arcsecond_downloads_total" tabindex="-1"><code>ARCSECOND_DOWNLOADS_TOTAL</code> <a class="header-anchor" href="#arcsecond_downloads_total" aria-label="Permalink to “ARCSECOND_DOWNLOADS_TOTAL”">​</a></h2><p><em>Set by the operator.</em> How many downloads the installation serves at once, all computers together. Default 24.</p><h2 id="arcsecond_download_rate" tabindex="-1"><code>ARCSECOND_DOWNLOAD_RATE</code> <a class="header-anchor" href="#arcsecond_download_rate" aria-label="Permalink to “ARCSECOND_DOWNLOAD_RATE”">​</a></h2><p><em>Set by the operator.</em> The speed of each download, in bytes per second, <code>k</code> and <code>m</code> allowed; <code>0</code> for no limit. Default <code>20m</code>. Lower it when the observers work remotely over a link the downloads would otherwise fill.</p><h2 id="arcsecond_backend_memory" tabindex="-1"><code>ARCSECOND_BACKEND_MEMORY</code> <a class="header-anchor" href="#arcsecond_backend_memory" aria-label="Permalink to “ARCSECOND_BACKEND_MEMORY”">​</a></h2><p><em>Set by the operator.</em> The most memory the backend container may use, e.g. <code>6g</code> (the default). Past it, Docker restarts the busiest of its processes rather than letting the machine take memory from the database.</p><h2 id="arcsecond_worker_memory" tabindex="-1"><code>ARCSECOND_WORKER_MEMORY</code> <a class="header-anchor" href="#arcsecond_worker_memory" aria-label="Permalink to “ARCSECOND_WORKER_MEMORY”">​</a></h2><p><em>Set by the operator.</em> The same ceiling for the worker, which runs the exposures and procedures. Default <code>6g</code>.</p><h2 id="arcsecond_data_worker_memory" tabindex="-1"><code>ARCSECOND_DATA_WORKER_MEMORY</code> <a class="header-anchor" href="#arcsecond_data_worker_memory" aria-label="Permalink to “ARCSECOND_DATA_WORKER_MEMORY”">​</a></h2><p><em>Set by the operator.</em> The same ceiling for the data worker: zip archives, previews, storage pushes, backups. Default <code>3g</code>.</p><h2 id="arcsecond_data_worker_concurrency" tabindex="-1"><code>ARCSECOND_DATA_WORKER_CONCURRENCY</code> <a class="header-anchor" href="#arcsecond_data_worker_concurrency" aria-label="Permalink to “ARCSECOND_DATA_WORKER_CONCURRENCY”">​</a></h2><p><em>Set by the operator.</em> How many jobs the data worker runs at once. Default 2; each can hold a few hundred MB.</p><h2 id="arcsecond_api_image" tabindex="-1"><code>ARCSECOND_API_IMAGE</code> <a class="header-anchor" href="#arcsecond_api_image" aria-label="Permalink to “ARCSECOND_API_IMAGE”">​</a></h2><p><em>Set by the operator.</em> The image the backend, both workers, beat and the alerts consumer run instead of the published one: one built from the backend&#39;s sources, e.g. <code>arcsecond-api:latest</code>. Empty: the published image. Set ARCSECOND_API_PULL_POLICY to <code>never</code> with it, then <code>arcsecond restart</code>.</p><h2 id="arcsecond_api_pull_policy" tabindex="-1"><code>ARCSECOND_API_PULL_POLICY</code> <a class="header-anchor" href="#arcsecond_api_pull_policy" aria-label="Permalink to “ARCSECOND_API_PULL_POLICY”">​</a></h2><p><em>Set by the operator.</em> <code>never</code> when ARCSECOND_API_IMAGE names an image that exists on this machine only, so <code>arcsecond update</code> and <code>arcsecond start --pull</code> leave it alone rather than fail to download it. Default <code>missing</code>.</p><h2 id="arcsecond_web_image" tabindex="-1"><code>ARCSECOND_WEB_IMAGE</code> <a class="header-anchor" href="#arcsecond_web_image" aria-label="Permalink to “ARCSECOND_WEB_IMAGE”">​</a></h2><p><em>Set by the operator.</em> The image the web interface runs instead of the published one: one built from the webapp&#39;s sources, e.g. <code>arcsecond-web:latest</code>. Empty: the published image. Set ARCSECOND_WEB_PULL_POLICY to <code>never</code> with it, then <code>arcsecond restart web</code>.</p><h2 id="arcsecond_web_pull_policy" tabindex="-1"><code>ARCSECOND_WEB_PULL_POLICY</code> <a class="header-anchor" href="#arcsecond_web_pull_policy" aria-label="Permalink to “ARCSECOND_WEB_PULL_POLICY”">​</a></h2><p><em>Set by the operator.</em> <code>never</code> when ARCSECOND_WEB_IMAGE names an image that exists on this machine only, as ARCSECOND_API_PULL_POLICY does for the backend&#39;s. Default <code>missing</code>.</p>',68)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
